-- TEST HARNESS ONLY. Hand-mirrors prisma/schema.prisma so integration tests can run on a throwaway
-- embedded Postgres where Prisma's migration engine can't be downloaded. The real migration is
-- generated by `prisma migrate dev` and is the source of truth for your Supabase database.
CREATE TYPE "TransactionType" AS ENUM ('INCOME','EXPENSE');
CREATE TYPE "PaymentMethod" AS ENUM ('CASH','BANK_TRANSFER','POS','CREDIT');
CREATE TYPE "TransactionSource" AS ENUM ('MANUAL','INVOICE_PAYMENT','IMPORTED');
CREATE TYPE "ImportStatus" AS ENUM ('PENDING_REVIEW','COMPLETED');
CREATE TYPE "ImportDirection" AS ENUM ('IN','OUT');
CREATE TYPE "MatchStatus" AS ENUM ('VALID','INVALID','DUPLICATE','UNMATCHED','SUGGESTED_MATCH','MATCHED');

CREATE TABLE "Business" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'NGN',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);

CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,
  "name" TEXT NOT NULL, "email" TEXT, "phone" TEXT, "notes" TEXT, "archivedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX ON "Customer"("businessId","name");

CREATE TABLE "Invoice" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,
  "customerId" TEXT NOT NULL REFERENCES "Customer"("id") ON DELETE RESTRICT, "invoiceNumber" TEXT NOT NULL,
  "issueDate" DATE NOT NULL, "dueDate" DATE NOT NULL, "isDraft" BOOLEAN NOT NULL DEFAULT false, "voidedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL,
  UNIQUE ("businessId","invoiceNumber"));
CREATE INDEX ON "Invoice"("businessId","dueDate");
CREATE INDEX ON "Invoice"("customerId");

CREATE TABLE "InvoiceItem" ("id" TEXT PRIMARY KEY, "invoiceId" TEXT NOT NULL REFERENCES "Invoice"("id") ON DELETE CASCADE,
  "description" TEXT NOT NULL, "quantity" DECIMAL(12,2) NOT NULL, "unitPrice" DECIMAL(14,2) NOT NULL);
CREATE INDEX ON "InvoiceItem"("invoiceId");

CREATE TABLE "InvoicePayment" ("id" TEXT PRIMARY KEY, "invoiceId" TEXT NOT NULL REFERENCES "Invoice"("id") ON DELETE RESTRICT,
  "amount" DECIMAL(14,2) NOT NULL, "paymentDate" DATE NOT NULL, "method" "PaymentMethod" NOT NULL, "reference" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL,
  UNIQUE ("invoiceId","reference"));
CREATE INDEX ON "InvoicePayment"("invoiceId");

CREATE TABLE "ReconciliationImport" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,
  "filename" TEXT NOT NULL, "status" "ImportStatus" NOT NULL DEFAULT 'PENDING_REVIEW', "rowCount" INTEGER NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX ON "ReconciliationImport"("businessId");

CREATE TABLE "ImportedTransaction" ("id" TEXT PRIMARY KEY, "importId" TEXT NOT NULL REFERENCES "ReconciliationImport"("id") ON DELETE CASCADE,
  "externalReference" TEXT, "date" DATE, "description" TEXT, "amount" DECIMAL(14,2), "direction" "ImportDirection",
  "matchStatus" "MatchStatus" NOT NULL, "matchedInvoiceId" TEXT REFERENCES "Invoice"("id") ON DELETE RESTRICT,
  "suggestedInvoiceId" TEXT, "createdTransactionId" TEXT, "rawRowNumber" INTEGER NOT NULL, "note" TEXT);
CREATE INDEX ON "ImportedTransaction"("importId");
CREATE INDEX ON "ImportedTransaction"("externalReference");

CREATE TABLE "Transaction" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,
  "customerId" TEXT REFERENCES "Customer"("id") ON DELETE RESTRICT, "type" "TransactionType" NOT NULL,
  "source" "TransactionSource" NOT NULL DEFAULT 'MANUAL', "paymentMethod" "PaymentMethod", "amount" DECIMAL(14,2) NOT NULL,
  "category" TEXT NOT NULL, "date" DATE NOT NULL, "description" TEXT, "reference" TEXT,
  "invoicePaymentId" TEXT UNIQUE REFERENCES "InvoicePayment"("id") ON DELETE RESTRICT,
  "importedTransactionId" TEXT UNIQUE REFERENCES "ImportedTransaction"("id") ON DELETE RESTRICT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX ON "Transaction"("businessId","date");
CREATE INDEX ON "Transaction"("businessId","type","date");
CREATE INDEX ON "Transaction"("businessId","category");

CREATE TABLE "AuditEvent" ("id" TEXT PRIMARY KEY, "businessId" TEXT NOT NULL REFERENCES "Business"("id") ON DELETE RESTRICT,
  "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "summary" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ON "AuditEvent"("businessId","createdAt");
